-- ===========================================================================
-- WHAT EVERY METATILE HOENN PLACES IS MADE OF.  Generated; do not hand-edit.
--
-- Built by walking all 518 Gen 3 maps, recording every metatile placed and
-- the collision and elevation the blockdata pairs it with, then reading the
-- sixteen pixel rows of its art and reducing each to a material.  10,943 rows
-- over 72 owning tilesets.
--
-- WHY THIS EXISTS.  Every terrain pass in this mod used to infer what a cell
-- was from whatever was to hand -- one pixel's colour, how tall the drawing
-- happened to be, whether the cell was walkable -- and each inference was
-- wrong somewhere: a purple rock became a skyscraper, a house's siding became
-- a cliff, a tree became a clifftop.  This answers the question once, from
-- the cartridge.
--
-- WHAT A ROW SAYS, and what it deliberately does NOT.
--
--   { art, material, cap, face, kind, motif, axis, facing, ledge }
--
--   art       "surface" every pixel row is a top -- grass, sand, worked stone
--             "face"    every row is a vertical material
--             "brow"    surface rows and then face rows: the drawn lip of a
--                       drop.  `cap` is the row it turns over at and `face`
--                       is how many rows of wall follow.
--             "banded"  alternating rows of worked material: treads, decking
--   material  "rock" "green" "sand" "stone"/"manmade" "water" -- what it is
--             DRAWN in, which is what tells a crater wall from a house wall
--             when both are blocked and both sit at elevation 0
--   cap/face  the row index the drawing turns over at, and the wall rows
--             below it.  104 is {"brow","rock",8,8}: eight pixels of terrace
--             top, eight of face.
--   kind      the cartridge's own word where it has one -- "water", "ledge",
--             "tree", "mountain" (MB_MOUNTAIN_TOP)
--   axis      for a tread, WHICH WAY IT CLIMBS -- "y" when the bands are
--             horizontal (a north-south flight), "x" when they are vertical.
--             Taken from the same periodicity test along the other axis, and
--             Hoenn is emphatic about it: Mt Pyre's 175 and Sootopolis' 580
--             both read rows repeating exactly over an 80-120 drop with their
--             columns dead flat.  Without this a flight's direction was
--             inferred from which pair of landings happened to sit further
--             apart, which turned north-south staircases in Sootopolis into
--             east-west ones.
--   facing    which side of a cliff run is the HIGHER ground.  Emerald draws
--             a south-facing cliff with the terrace on top and the wall below
--             it -- 104 is nine rows of grass over seven of rock -- so the
--             high side is NORTH and the row reads "S".  It also draws
--             north-facing rims (38 of them in the General tileset, 120 among
--             them) where the wall is on top and the terrace below, high side
--             SOUTH, and the row reads "N".  A pure face carries no facing;
--             the direction of a run comes from the brow that caps it.
--   ledge     true when the drawing contains a hard SHADOW LINE -- one row
--             far darker than the rows either side.  That is what one course
--             of masonry looks like from the south, and counting them up a
--             cliff run is how tall the cliff is.  Sootopolis' terrace edge,
--             577, reads 220 211 [106] 229 229 255 208 169 ... 169 [81] 133
--             and is true; its raised BODY, 737, reads 206 189 179 165 159
--             158 ... and is false, as is the street 729 and the treads 580.
--             A pure `face` metatile -- the crater's rust wall, an ash bank --
--             has no shadow line because the whole cell IS the front face;
--             those count as a course on the art field instead.
--   motif     true when nothing with a face is ever drawn beneath this cell,
--             so it is foliage or a standalone object and not the top of a
--             drop.  Hoenn's trees are 468 over 476: all green, blocked, at
--             elevation 0, indistinguishable from a grassy clifftop until you
--             ask what is underneath them.
--
-- IT DOES NOT SAY WHETHER YOU CAN WALK ON IT.  In Gen 3 collision belongs to
-- the CELL, not the metatile: Route 111's desert plateau and the wall holding
-- it up are both metatile 113, 3490 cells of it blocked and 2242 walkable.
-- Asked of a metatile, "is this a cliff" has no answer.  Asked of the art it
-- does, and the blockdata resolves the rest per cell -- see Gen3.roleAt.
--
-- The id space is split: 0..511 come from the map's PRIMARY tileset and
-- 512..1023 from its SECONDARY, so rows are keyed by the tileset that OWNS
-- the metatile ("P" or "S" and the tileset address).  Hoenn has three
-- primaries and seventy secondaries; keying by the 75 PAIRS instead would
-- have described the General tileset's cliffs seventy-five times over.
-- ===========================================================================
